#!/usr/bin/env python3
"""Writes ../provenance.md from manifest.json (re-run after render.py; picks up approved asset paths)."""
import json, os, glob
APPROVED = '/workspace/tag-brand/approved'
def original_of(path):
    """For a clean/ cutout, return the original approved file it was made from (same stem, any extension)."""
    if '/clean/' not in path: return None
    stem = os.path.splitext(os.path.basename(path))[0]
    c = [f for f in glob.glob(f'{APPROVED}/{stem}.*')]
    return c[0] if c else None
def src(path):
    o = original_of(path)
    return f'`{path}` (clean background-removed cutout; original source `{o}`)' if o else f'`{path}`'
ROOT = '/workspace/tag-brand/day1-v2'
m = json.load(open(f'{ROOT}/src/manifest.json'))
FONTNAME = {'SpaceGrotesk': 'Space Grotesk (Bold 700)', 'Inter-': 'Inter (Regular 400)', 'IBMPlexSans': 'IBM Plex Sans (Bold 700 + Regular 400)'}
L = ['# TAG day 1 v2 — asset provenance', '',
     '**Neil selected Variant A on 3 Nov 2026** (Space Grotesk Bold + Inter Regular). Variant A files are final; Variant B files (IBM Plex Sans) are kept for reference only.', '',
     'Generated by `src/render.py` (HTML + inline SVG rendered with headless Chrome). DRAFTS: nothing has been posted, uploaded or sent.', '',
     '**No generated imagery was created for this set.** No AI image or video generation was run, and there is no stock, game art, third-party logos or UI. Everything except the approved files listed below is type plus simple geometry drawn in code (lines, rectangles, circles, an EQ curve computed from RBJ biquad filter maths). Approved files (Neil’s, from /workspace/tag-brand/approved/) are only scaled proportionally and placed, never edited, recoloured, masked, cropped or given effects. They are the TAG logo on all 24 assets, Haggis (arms crossed) on Post 5 only, and neon line-art glyph icons on Posts 1, 2, 4 and 6 (supplied cyan, not recoloured). Both now come from the clean transparent cutouts in /workspace/tag-brand/approved/clean/ (see its README.md); each entry records the clean path and its original source.', '',
     'Fonts: all SIL Open Font License 1.1 (licence text embedded in each font file’s name table, ID 13).', '',
     '- Space Grotesk v2.000, OFL 1.1: `/usr/share/fonts/truetype/sand-box/google/Space Grotesk/SpaceGrotesk-VariableFont_wght.ttf`',
     '- Inter v4.001, OFL 1.1: `/usr/share/fonts/truetype/sand-box/google/Inter/Inter-VariableFont_opsz,wght.ttf`',
     '- IBM Plex Sans v3.201, OFL 1.1: `/usr/share/fonts/truetype/sand-box/google/IBM Plex Sans/IBMPlexSans-VariableFont_wdth,wght.ttf`', '',
     'Palette: background #000000, text #F2F0EB, single accent TAG blue #1E7BFF (no orange).', '',
     '## Fact sources (checked 3 Nov 2026)', '',
     '- **P1: GTA VI PS5 pre-load opens 10 Nov.** CONFIRMED. PlayStation.Blog, 3 Nov 2026: "pre-download available starting November 10 … to those who pre-order starting at November 10 local midnight": https://blog.playstation.com/2026/11/03/grand-theft-auto-vi-pre-download-begins-november-10/ . Also PlayStation game page: https://www.playstation.com/en-us/games/grand-theft-auto-vi/',
     '- **P3: OBS 33 Safe Mode skips third-party plugins and the WebSocket server.** CONFIRMED. OBS Studio 33.0.0 release notes: "Changed Safe Mode to not start WebSocket Server" and "Third-party plugins are not loaded at all in Safe Mode": https://github.com/obsproject/obs-studio/releases/tag/33.0.0 . Secondary: https://www.elgato.com/us/en/explorer/news/streaming/obs-studio-33-0-update-whats-new/',
     '- **P4: Phasmophobia Resonance update, late Nov, reworking the Sound Sensor map.** CONFIRMED. Kinetic Games, Development Preview #22: Resonance "launching in late November"; "We’re reworking the UI on the Sensor’s map … a looping sound will stick around for a while whereas a single sound will ping once and disappear": https://kineticgames.co.uk/news/phasmophobia-development-preview-22 . No exact date has been announced.',
     '- **P6: Stream Recaps.** CONFIRMED and on-image copy matched to the official wording. Twitch blog “Introducing Stream Recaps”, 20 Oct 2026: “A Stream Recap is a highlight reel of clips from a livestream”; “Your followers can find the Recap in a shelf at the top of their mobile feed. Recaps also live on your channel page.”; “By default, clips made by you and your editors are included in the Stream Recap, but you can easily remove, add or edit clips at any point.” https://blog.twitch.tv/en/2026/10/20/stream-recaps/', '',
     '## Approvals', '', '- Post 5 (A4G closed launch, MultiChat, Studio Apps): approved by Neil for public use on 3 Nov 2026. No longer on HOLD.', '']
for out in sorted(m):
    e = m[out]
    fonts = []
    for f in dict.fromkeys(e['fonts']):
        nm = next(v for k, v in FONTNAME.items() if k in f); fonts.append(f'{nm}, OFL 1.1, `{f}`')
    logo = (f'logo: stand-in derived from X avatar, NOT approved master (`{e["logo"]}`, pasted unmodified as a square tile on #000000)'
            if e['logo_stand_in'] else f'logo: approved master {src(e["logo"])}')
    L += [f'## {os.path.relpath(out, ROOT)}' , '',
          f'- Post {e["post"]}, Variant {e["variant"]}' + (' (FINAL: Neil selected Variant A on 3 Nov 2026)' if e['variant'] == 'A' else ' (not selected; reference only)'),
          f'- {logo}',
          f'- icon: ' + (f'approved neon glyph, unaltered, Lanczos-downscaled only: clean `{e["icon"]}`; original source `{e.get("icon_original")}`; rendered copy `{e.get("icon_rendered")}`' if e['icon'] else 'none (by design for this post)'),
          '- fonts: ' + '; '.join(fonts),
          '- character: ' + (f'Haggis (arms crossed), approved file used as supplied, proportional scale only (body alpha 250–254 left unchanged): {src(e["haggis"])}' if e.get('haggis') else 'none'),
          '- A4G mark (`/workspace/tag-brand/approved/a4g-logo-blue.png`): not used',
          '- generated imagery: none'] + (['- Approval: Neil approved Post 5 for public use on 3 Nov 2026, including the A4G closed launch, MultiChat and Studio Apps mentions (previous HOLD lifted).'] if e['post'] == 5 else []) + ['']
L += ['## Not used', '', '- `/workspace/tag-brand/avatar.jpg` and `src/logo.png` (earlier stand-ins derived from the X avatar) and the original `approved/tag-logo-metallic.jpg` tile are no longer placed directly; the clean cutout is used instead.',
      '- Icon tiles (clean/icon-*-tile.png) are never used; only -glyph.png files, on posts 1, 2, 4 and 6. No shield exists, so P3 has no icon; P5 has Haggis instead.',
      '- `haggis-squatting-on-black.jpg` (opaque) is not used, as instructed.', '']
# Preserve any hand-added '## ' sections from the existing provenance.md that this script doesn't generate
out = f'{ROOT}/provenance.md'
generated = {l for l in L if l.startswith('## ')}
kept = []
if os.path.exists(out):
    cur, buf = None, []
    for line in open(out).read().split('\n') + ['## __end__']:
        if line.startswith('## '):
            if cur and cur not in generated: kept.append('\n'.join(buf).rstrip() + '\n')
            cur, buf = line, [line]
        elif cur: buf.append(line)
open(out, 'w').write('\n'.join(L).rstrip() + '\n' + ('\n' + '\n'.join(kept) if kept else ''))
print('ok', len(m), 'preserved:', [k.split('\n')[0] for k in kept])
